<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { supabase } from '../lib/supabase'
import { auth } from '../stores/auth'
const count = ref(0); const loading = ref(true); const saving = ref(false); const error = ref(''); const saved = ref(''); const limit = computed(() => auth.plan?.character_limit ?? 0); const displayName = ref(''); const editing = ref(false); const fieldError = ref('')
const profile = reactive({ display_name: '' })
onMounted(async () => { const [{ count: value }, { data }] = await Promise.all([supabase.from('characters').select('id', { count: 'exact', head: true }), supabase.from('profiles').select('display_name').eq('id', auth.user?.id).maybeSingle()]); count.value = value || 0; profile.display_name = data?.display_name || ''; displayName.value = profile.display_name; loading.value = false })
async function saveProfile() { fieldError.value = ''; saved.value = ''; if (displayName.value.length > 50) { fieldError.value = 'Display name must be 50 characters or fewer.'; return }; saving.value = true; const { data, error: updateError } = await supabase.from('profiles').update({ display_name: displayName.value }).eq('id', auth.user?.id).select().maybeSingle(); saving.value = false; if (updateError || !data) { error.value = 'Your display name could not be saved.'; return }; auth.profile = data; profile.display_name = data.display_name; editing.value = false; saved.value = 'Profile saved.' }
</script>
<template><section class="page"><div class="eyebrow">Your keeper profile</div><h2>Account</h2><p v-if="error" class="form-error">{{ error }}</p><p v-if="saved" class="saved-message">{{ saved }}</p><div v-if="loading" class="empty"><p class="muted">Loading account…</p></div><div v-else class="account-grid"><div class="detail-card"><div class="eyebrow">Identity</div><h3 v-if="!editing">{{ auth.profile?.display_name || auth.user?.email }}</h3><input v-else v-model="displayName" class="account-input" maxlength="50" /><p class="muted">{{ auth.user?.email }}</p><p v-if="fieldError" class="field-error">{{ fieldError }}</p><div class="account-actions"><button v-if="!editing" class="outline" @click="editing = true">Edit profile</button><template v-else><button class="primary" :disabled="saving" @click="saveProfile">{{ saving ? 'Saving…' : 'Save profile' }}</button><button class="outline" @click="editing = false">Cancel</button></template></div></div><div class="detail-card plan-summary"><div class="eyebrow">Current plan</div><h3>{{ auth.plan?.name }}</h3><p>{{ auth.plan?.price_cents ? `$${auth.plan.price_cents / 100} per month` : 'Free plan' }}</p><RouterLink class="text-link" to="/plans">Compare plans →</RouterLink></div><div class="detail-card usage-card"><div class="section-heading"><div><div class="eyebrow">Character usage</div><h3>{{ count }} of {{ limit }} slots used</h3></div><strong>{{ Math.max(0, limit - count) }} remaining</strong></div><div class="usage-track"><i :style="{ width: `${Math.min(100, count / Math.max(1, limit) * 100)}%` }"></i></div><p class="muted">{{ count }} of {{ limit }} slots used · {{ Math.max(0, limit - count) }} remaining</p></div></div></section></template>
